package com.ouisani.aios.core.dream;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 规则写入器 — 借鉴 Headroom learn/writer.py。
 * <p>
 * 将 {@link SessionAnalyzer} 生成的推荐规则写入持久化文件，
 * 使用标记分隔的区块管理 — 借鉴 Headroom 的 marker-delimited section。
 * <p>
 * <b>标记格式：</b>
 * <pre>
 * &lt;!-- aios:learn:start --&gt;
 * ## AIOS Learned Patterns
 * *Auto-generated by SessionAnalyzer on 2026-06-25 — do not edit manually*
 *
 * ### Loop Guardrail: bash - error-loop
 * ~5000 tokens/session saved
 * Do NOT retry this command more than once...
 *
 * ### Avoid Reading Non-existent Files
 * ~200 tokens/session saved
 * Always check file exists with glob before reading...
 * &lt;!-- aios:learn:end --&gt;
 * </pre>
 * <p>
 * <b>合并策略（借鉴 Headroom _merge_recommendations）：</b>
 * 新规则覆盖同名旧规则；旧规则中未在新运行中出现的段落会被保留，
 * 避免重新运行时丢失已积累的学习成果。
 * <p>
 * OS 类比：相当于 Linux 的 sysctl.conf — 持久化的内核参数调整规则。
 */
public class LearnRuleWriter {

    private static final Logger log = LoggerFactory.getLogger(LearnRuleWriter.class);

    /** 标记分隔符 — 借鉴 Headroom _MARKER_START/_MARKER_END */
    public static final String MARKER_START = "<!-- aios:learn:start -->";
    public static final String MARKER_END = "<!-- aios:learn:end -->";

    /** 标记区块正则 — 匹配整个 learn 区块 */
    private static final Pattern MARKER_PATTERN = Pattern.compile(
            Pattern.quote(MARKER_START) + ".*?" + Pattern.quote(MARKER_END),
            Pattern.DOTALL);

    /** tokens/session saved 注解正则 */
    private static final Pattern TOKENS_ANNOTATION_PATTERN =
            Pattern.compile("\\*~([\\d,]+) tokens/session saved\\*\\n?");

    /** 默认规则文件名 */
    public static final String DEFAULT_RULES_FILE = "learned_rules.md";

    // ════════════════════════════════════════════════════════════════
    //  写入方法
    // ════════════════════════════════════════════════════════════════

    /**
     * 将推荐规则写入文件 — 借鉴 Headroom ContextWriter.write()。
     * <p>
     * 使用标记分隔的区块，与现有文件内容共存：
     * <ul>
     *   <li>如果文件已有标记区块，替换区块内容（合并新旧规则）</li>
     *   <li>如果文件没有标记区块，在末尾追加</li>
     *   <li>如果文件不存在，创建新文件</li>
     * </ul>
     *
     * @param filePath        目标文件路径
     * @param recommendations 推荐规则列表
     * @param dryRun          true 只返回内容不写入文件
     * @return 写入结果
     */
    public static WriteResult write(Path filePath,
                                     List<LearnRecommendation> recommendations,
                                     boolean dryRun) {
        WriteResult result = new WriteResult();

        if (recommendations == null || recommendations.isEmpty()) {
            log.info("[LearnRuleWriter] 无推荐规则可写入");
            result.notice = "No recommendations to write";
            return result;
        }

        // 合并新旧规则
        List<LearnRecommendation> merged = mergeRecommendations(filePath, recommendations);

        // 构建区块内容
        String section = buildSection(merged);

        // 合并到文件
        String fileContent = mergeIntoFile(filePath, section);

        result.content = fileContent;
        result.recommendationCount = merged.size();
        result.loopGuardrailCount = (int) merged.stream()
                .filter(LearnRecommendation::isLoopGuardrail).count();

        if (!dryRun) {
            try {
                Files.createDirectories(filePath.getParent());
                Files.writeString(filePath, fileContent, StandardCharsets.UTF_8);
                result.fileWritten = filePath;
                log.info("[LearnRuleWriter] 已写入 {} 条规则到 {} (循环护栏: {})",
                        merged.size(), filePath, result.loopGuardrailCount);
            } catch (IOException e) {
                log.error("[LearnRuleWriter] 写入失败: {}", e.getMessage());
                result.error = e.getMessage();
            }
        } else {
            log.info("[LearnRuleWriter] Dry run: {} 条规则将写入 {} (循环护栏: {})",
                    merged.size(), filePath, result.loopGuardrailCount);
        }

        return result;
    }

    /** 便捷方法：写入默认规则文件 */
    public static WriteResult writeToDefault(String dir,
                                              List<LearnRecommendation> recommendations,
                                              boolean dryRun) {
        return write(Path.of(dir, DEFAULT_RULES_FILE), recommendations, dryRun);
    }

    // ════════════════════════════════════════════════════════════════
    //  区块构建 — 借鉴 Headroom _build_section()
    // ════════════════════════════════════════════════════════════════

    /**
     * 构建标记分隔的区块内容。
     */
    private static String buildSection(List<LearnRecommendation> recommendations) {
        String date = LocalDate.now().toString();
        StringBuilder sb = new StringBuilder();

        sb.append(MARKER_START).append("\n");
        sb.append("## AIOS Learned Patterns\n");
        sb.append("*Auto-generated by SessionAnalyzer on ").append(date)
                .append(" — do not edit manually*\n\n");

        for (LearnRecommendation rec : recommendations) {
            sb.append("### ").append(rec.section()).append("\n");
            if (rec.estimatedTokensSaved() > 0) {
                sb.append(String.format("*~%,d tokens/session saved*\n", rec.estimatedTokensSaved()));
            }
            if (rec.isLoopGuardrail()) {
                sb.append(String.format("*LOOP GUARDRAIL (detected %dx)*\n", rec.loopOccurrences()));
            }
            sb.append(rec.content()).append("\n\n");
        }

        sb.append(MARKER_END);
        return sb.toString();
    }

    // ════════════════════════════════════════════════════════════════
    //  合并策略 — 借鉴 Headroom _merge_recommendations()
    // ════════════════════════════════════════════════════════════════

    /**
     * 合并新旧规则 — 新规则覆盖同名旧规则，未出现的旧规则保留。
     * <p>
     * 借鉴 Headroom _merge_recommendations()。
     */
    private static List<LearnRecommendation> mergeRecommendations(
            Path filePath, List<LearnRecommendation> newRecs) {

        if (!Files.exists(filePath)) {
            return newRecs;
        }

        List<LearnRecommendation> prior = parsePriorRecommendations(filePath);
        if (prior.isEmpty()) {
            return newRecs;
        }

        // 新规则的 section 集合
        Set<String> newSections = new HashSet<>();
        for (LearnRecommendation r : newRecs) {
            newSections.add(r.section());
        }

        // 保留旧规则中未在新运行中出现的
        List<LearnRecommendation> carried = new ArrayList<>();
        for (LearnRecommendation p : prior) {
            if (!newSections.contains(p.section())) {
                carried.add(p);
            }
        }

        // 合并：新规则优先 + 保留的旧规则
        List<LearnRecommendation> merged = new ArrayList<>(newRecs);
        merged.addAll(carried);
        return merged;
    }

    /**
     * 从现有文件中解析之前的推荐规则。
     * 借鉴 Headroom _parse_prior_recommendations()。
     */
    private static List<LearnRecommendation> parsePriorRecommendations(Path filePath) {
        try {
            String content = Files.readString(filePath, StandardCharsets.UTF_8);
            Matcher matcher = MARKER_PATTERN.matcher(content);
            if (!matcher.find()) {
                return List.of();
            }

            // 提取标记区块内部内容
            String block = matcher.group(0);
            String inner = block.substring(MARKER_START.length(), block.length() - MARKER_END.length());

            List<LearnRecommendation> recs = new ArrayList<>();
            // 按 ### 标题分割
            String[] parts = ("\n" + inner).split("\n### ");

            for (int i = 1; i < parts.length; i++) {
                String part = parts[i];
                int newlineIdx = part.indexOf('\n');
                if (newlineIdx < 0) continue;

                String heading = part.substring(0, newlineIdx).strip();
                String body = part.substring(newlineIdx + 1);

                // 解析 tokens saved 注解
                int tokensSaved = 0;
                Matcher tokensMatcher = TOKENS_ANNOTATION_PATTERN.matcher(body);
                if (tokensMatcher.find()) {
                    tokensSaved = Integer.parseInt(tokensMatcher.group(1).replace(",", ""));
                    body = body.substring(tokensMatcher.end());
                }

                // 检查是否为循环护栏
                boolean isLoop = body.contains("*LOOP GUARDRAIL");
                int loopOccurrences = 0;
                if (isLoop) {
                    Pattern loopCount = Pattern.compile("\\*LOOP GUARDRAIL \\(detected (\\d+)x\\)\\*");
                    Matcher lm = loopCount.matcher(body);
                    if (lm.find()) {
                        loopOccurrences = Integer.parseInt(lm.group(1));
                    }
                    // 去掉标记行
                    body = body.replaceAll("\\*LOOP GUARDRAIL \\(detected \\d+x\\)\\*\\n?", "");
                }

                LearnRecommendation rec = new LearnRecommendation(
                        LearnRecommendation.Target.CONTEXT_FILE,
                        heading, body.strip(),
                        0.5, 1, tokensSaved
                );
                if (isLoop) {
                    rec.setLoopGuardrail(true);
                    rec.setLoopOccurrences(loopOccurrences);
                }
                recs.add(rec);
            }

            return recs;
        } catch (Exception e) {
            log.warn("[LearnRuleWriter] 解析旧规则失败: {}", e.getMessage());
            return List.of();
        }
    }

    /**
     * 将区块合并到文件 — 借鉴 Headroom _merge_into_file()。
     */
    private static String mergeIntoFile(Path filePath, String section) {
        try {
            if (!Files.exists(filePath)) {
                return section + "\n";
            }

            String existing = Files.readString(filePath, StandardCharsets.UTF_8);
            if (existing.contains(MARKER_START)) {
                // 替换已有区块
                return MARKER_PATTERN.matcher(existing).replaceAll(
                        java.util.regex.Matcher.quoteReplacement(section));
            } else {
                // 追加到末尾
                return existing.stripTrailing() + "\n\n" + section + "\n";
            }
        } catch (IOException e) {
            return section + "\n";
        }
    }

    // ════════════════════════════════════════════════════════════════
    //  读取方法 — 供 ContextInjector 使用
    // ════════════════════════════════════════════════════════════════

    /**
     * 从文件中提取标记区块的原始文本。
     * 借鉴 Headroom extract_marker_block()。
     *
     * @param filePath 文件路径
     * @return 标记区块文本，不存在返回 null
     */
    public static String extractMarkerBlock(Path filePath) {
        try {
            String content = Files.readString(filePath, StandardCharsets.UTF_8);
            Matcher matcher = MARKER_PATTERN.matcher(content);
            return matcher.find() ? matcher.group(0) : null;
        } catch (IOException e) {
            return null;
        }
    }

    /**
     * 从文件中解析所有推荐规则。
     */
    public static List<LearnRecommendation> loadRules(Path filePath) {
        return parsePriorRecommendations(filePath);
    }

    // ════════════════════════════════════════════════════════════════
    //  写入结果
    // ════════════════════════════════════════════════════════════════

    /** 写入结果 */
    public static class WriteResult {
        public Path fileWritten;
        public String content;
        public int recommendationCount;
        public int loopGuardrailCount;
        public String error;
        public String notice;

        public boolean success() {
            return error == null;
        }

        @Override
        public String toString() {
            if (error != null) {
                return "WriteResult{error='" + error + "'}";
            }
            return String.format("WriteResult{rules=%d, loops=%d, file=%s}",
                    recommendationCount, loopGuardrailCount, fileWritten);
        }
    }
}
